-- Invite
ALTER TABLE "Invite" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Invite" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Invite_tenant_isolation" ON "Invite";
DROP POLICY IF EXISTS "Invite_readable" ON "Invite";
CREATE POLICY "Invite_tenant_isolation" ON "Invite"
  FOR ALL
  USING (("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ',')) OR current_setting('app.is_superuser', true) = '1'))
  WITH CHECK (("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ',')) OR current_setting('app.is_superuser', true) = '1'));

  -- …and the single row whose code somebody has just typed in, which is
  -- how a join code names the school it belongs to.
  -- …and a PENDING invitation addressed to the caller's own VERIFIED
  -- email — what lets /join offer the invitation instead of "go back
  -- to your inbox". See ADDRESSEE_READABLE in scripts/gen-rls.ts.
  -- All are in a SELECT-ONLY policy: readable, never writable.
CREATE POLICY "Invite_readable" ON "Invite"
  FOR SELECT
  USING (("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ',')) OR current_setting('app.is_superuser', true) = '1')
         OR "tokenHash" = current_setting('app.join_code', true)
         OR ("Invite"."status" = 'PENDING'
            AND current_setting('app.user_id', true) <> ''
            AND lower("Invite"."email") = (
              SELECT lower(u."email") FROM "User" u
              WHERE u."id" = current_setting('app.user_id', true)
                AND u."emailVerifiedAt" IS NOT NULL
            ))
        );

-- Notification
ALTER TABLE "Notification" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Notification" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Notification_tenant_isolation" ON "Notification";
DROP POLICY IF EXISTS "Notification_readable" ON "Notification";
CREATE POLICY "Notification_tenant_isolation" ON "Notification"
  FOR ALL
  USING ("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ',')))
  WITH CHECK ("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ',')));

  -- Reads also allow your OWN rows, which is what lets a login ask
  -- which schools you belong to before any school is known.
  -- It is in a SELECT-ONLY policy: readable, never writable.
CREATE POLICY "Notification_readable" ON "Notification"
  FOR SELECT
  USING ("schoolId" = ANY (string_to_array(current_setting('app.school_ids', true), ','))
         OR "userId" = current_setting('app.user_id', true)
        );

  -- Your own notices are yours to finish and discard, whichever
  -- school wrote them. See the note in scripts/gen-rls.ts above the
  -- Notification self policies.
DROP POLICY IF EXISTS "Notification_self_update" ON "Notification";
CREATE POLICY "Notification_self_update" ON "Notification"
  FOR UPDATE
  USING (current_setting('app.user_id', true) <> ''
          AND "userId" = current_setting('app.user_id', true))
  WITH CHECK (current_setting('app.user_id', true) <> ''
          AND "userId" = current_setting('app.user_id', true));
DROP POLICY IF EXISTS "Notification_self_delete" ON "Notification";
CREATE POLICY "Notification_self_delete" ON "Notification"
  FOR DELETE
  USING (current_setting('app.user_id', true) <> ''
          AND "userId" = current_setting('app.user_id', true));

